+  onSuccess?: () => void
+}
+
+export default function RegisterForm({ onSuccess }: Props) {
+  const idPrefix = useId()
+
+  const [name, setName] = useState("")
+  const [email, setEmail] = useState("")
+  const [password, setPassword] = useState("")
+  const [passwordConfirm, setPasswordConfirm] = useState("")
+  const [showPassword, setShowPassword] = useState(false)
+  const [showPasswordConfirm, setShowPasswordConfirm] = useState(false)
+  const [submitting, setSubmitting] = useState(false)
+  const [serverError, setServerError] = useState<string | null>(null)
+  const [successMessage, setSuccessMessage] = useState<string | null>(null)
+
+  const [fieldErrors, setFieldErrors] = useState<{
+    name?: string
+    email?: string
+    password?: string
+    passwordConfirm?: string
+  }>({})
+
+  function validate(): boolean {
+    const errs: typeof fieldErrors = {}
+
+    if (!name.trim()) {
+      errs.name = "必須項目です。"
+    }
+
+    const emailRe = /^[A-Za-z0-9._%+-]+@ginga\.info$/
+    if (!email.trim()) {
+      errs.email = "必須項目です。"
+    } else if (!emailRe.test(email.trim())) {
+      errs.email = "@ginga.info ドメインのメールアドレスを入力してください。"
+    }
+
+    if (!password) {
+      errs.password = "必須項目です。"
+    } else if (password.length < 8) {
+      errs.password = "パスワードは8文字以上で入力してください。"
+    }
+
+    if (!passwordConfirm) {
+      errs.passwordConfirm = "必須項目です。"
+    } else if (password !== passwordConfirm) {
+      errs.passwordConfirm = "パスワードが一致しません。"
+    }
+
+    setFieldErrors(errs)
+    return Object.keys(errs).length === 0
+  }
+
+  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
+    e.preventDefault()
+    setServerError(null)
+    setSuccessMessage(null)
+
+    if (!validate()) return
+
+    setSubmitting(true)
+    try {
+      const res = await fetch("/api/v1/auth/register", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({
+          username: name.trim(),
+          email: email.trim(),
+          password,
+        }),
+      })
+
+      const data = await res.json().catch(() => ({}))
+
+      if (!res.ok) {
