+    } catch (err: unknown) {
+      const message = err instanceof Error ? err.message : "ネットワークエラーが発生しました。"
+      setServerError(message)
+    } finally {
+      setSubmitting(false)
+    }
+  }
+
+  return (
+    <form onSubmit={handleSubmit} aria-live="polite" noValidate className={styles.form}>
+
+      {/* 名前 */}
