+        {fieldErrors.name && (
+          <div id={`${idPrefix}-name-error`} role="alert" className={styles.fieldError}>
+            {fieldErrors.name}
+          </div>
+        )}
+      </div>
+
+      {/* メールアドレス */}
+      <div className={styles.field}>
+        <label className={styles.label} htmlFor={`${idPrefix}-email`}>
+          メールアドレス
+          <span className={styles.fieldHint}>（@ginga.info ドメインのみ）</span>
+        </label>
+        <input
+          className={styles.input}
+          id={`${idPrefix}-email`}
+          name="email"
+          type="email"
+          value={email}
+          onChange={(e) => {
+            setEmail(e.target.value)
+            setFieldErrors((s) => ({ ...s, email: undefined }))
+          }}
+          required
+          aria-invalid={!!fieldErrors.email}
+          aria-describedby={fieldErrors.email ? `${idPrefix}-email-error` : undefined}
+          autoComplete="email"
+          placeholder="例: taro@ginga.info"
+        />
+        {fieldErrors.email && (
+          <div id={`${idPrefix}-email-error`} role="alert" className={styles.fieldError}>
+            {fieldErrors.email}
+          </div>
+        )}
+      </div>
+
+      {/* パスワード */}
+      <div className={styles.field}>
+        <label className={styles.label} htmlFor={`${idPrefix}-password`}>
+          パスワード
+          <span className={styles.fieldHint}>（8文字以上）</span>
+        </label>
+        <div style={{ display: "flex", gap: 8 }}>
+          <input
+            className={styles.input}
+            id={`${idPrefix}-password`}
+            name="password"
+            type={showPassword ? "text" : "password"}
+            value={password}
+            onChange={(e) => {
+              setPassword(e.target.value)
+              setFieldErrors((s) => ({ ...s, password: undefined }))
+            }}
+            required
+            aria-invalid={!!fieldErrors.password}
+            aria-describedby={fieldErrors.password ? `${idPrefix}-password-error` : undefined}
+            autoComplete="new-password"
+          />
+          <button
+            type="button"
+            className={styles.toggleButton}
+            onClick={() => setShowPassword((s) => !s)}
+            aria-pressed={showPassword}
+          >
+            {showPassword ? "非表示" : "表示"}
+          </button>
+        </div>
+        {fieldErrors.password && (
+          <div id={`${idPrefix}-password-error`} role="alert" className={styles.fieldError}>
+            {fieldErrors.password}
+          </div>
+        )}
+      </div>
+
+      {/* パスワード（確認） */}
+      <div className={styles.field}>
+        <label className={styles.label} htmlFor={`${idPrefix}-passwordConfirm`}>
+          パスワード（確認）
+        </label>
+        <div style={{ display: "flex", gap: 8 }}>
+          <input
+            className={styles.input}
+            id={`${idPrefix}-passwordConfirm`}
+            name="passwordConfirm"
+            type={showPasswordConfirm ? "text" : "password"}
+            value={passwordConfirm}
+            onChange={(e) => {
+              setPasswordConfirm(e.target.value)
+              setFieldErrors((s) => ({ ...s, passwordConfirm: undefined }))
+            }}
+            required
+            aria-invalid={!!fieldErrors.passwordConfirm}
+            aria-describedby={
+              fieldErrors.passwordConfirm ? `${idPrefix}-passwordConfirm-error` : undefined
+            }
+            autoComplete="new-password"
+          />
+          <button
+            type="button"
+            className={styles.toggleButton}
+            onClick={() => setShowPasswordConfirm((s) => !s)}
+            aria-pressed={showPasswordConfirm}
+          >
+            {showPasswordConfirm ? "非表示" : "表示"}
+          </button>
+        </div>
+        {fieldErrors.passwordConfirm && (
+          <div
+            id={`${idPrefix}-passwordConfirm-error`}
+            role="alert"
+            className={styles.fieldError}
+          >
+            {fieldErrors.passwordConfirm}
+          </div>
+        )}
+      </div>
+
+      {/* サーバーエラー */}
+      {serverError && (
+        <div role="alert" aria-live="assertive" className={styles.error}>
+          {serverError}
+        </div>
+      )}
+
+      {/* 成功メッセージ */}
+      {successMessage && (
+        <div role="status" aria-live="polite" className={styles.successMessage}>
+          {successMessage}
+        </div>
+      )}
+
+      <div>
+        <button className={styles.button} type="submit" disabled={submitting}>
+          {submitting ? "送信中..." : "会員登録"}
+        </button>
+      </div>
+    </form>
+  )
+}"},{"fileName":"app/components/SearchResultList.tsx","patch":"@@ -0,0 +1,169 @@
+"use client"
+
+import React from "react"
+import Link from "next/link"
+import styles from "../styles/search_list.module.css"
+
+// ──────────────────────────────────────────────
+// 型定義
+// ──────────────────────────────────────────────
+
+export type Article = {
+  id: number | string
+  title: string
+  excerpt?: string
+  author?: string
+  publishedAt?: string
+  tags?: string[]
+}
+
+type Props = {
+  articles: Article[]
+  loading: boolean
+  error: string | null
+  /** 現在のページ番号（1始まり） */
+  page: number
+  /** 総ページ数 */
+  totalPages: number
+  onPageChange: (page: number) => void
+}
+
+// ──────────────────────────────────────────────
+// サブコンポーネント: 検索結果カード
+// ──────────────────────────────────────────────
+
+function ResultCard({ article }: { article: Article }) {
+  return (
+    <article className={styles.resultCard}>
+      <Link href={`/knowledge/${article.id}`} className={styles.resultCardLink}>
+        {article.title}
+      </Link>
+
+      {article.excerpt && (
+        <p className={styles.resultCardExcerpt}>{article.excerpt}</p>
+      )}
+
+      {article.tags && article.tags.length > 0 && (
+        <div className={styles.tagChipList}>
+          {article.tags.map((tag) => (
+            <span key={tag} className={styles.tagChip}>{tag}</span>
+          ))}
+        </div>
+      )}
+
+      <div className={styles.resultCardMeta}>
+        {article.author && <span>投稿者: {article.author}</span>}
+        {article.publishedAt && (
+          <span>
+            {new Date(article.publishedAt).toLocaleDateString("ja-JP")}
+          </span>
+        )}
+      </div>
+    </article>
+  )
+}
+
+// ──────────────────────────────────────────────
+// サブコンポーネント: ページネーション
+// ──────────────────────────────────────────────
+
+function Pagination({
+  page,
+  totalPages,
+  onPageChange,
+}: {
+  page: number
+  totalPages: number
+  onPageChange: (p: number) => void
+}) {
+  if (totalPages <= 1) return null
+
+  const pages: number[] = []
+  const delta = 2
+  for (let i = Math.max(1, page - delta); i <= Math.min(totalPages, page + delta); i++) {
+    pages.push(i)
+  }
+
+  return (
+    <nav className={styles.pagination} aria-label="ページネーション">
+      <button
+        className={styles.pageButton}
+        onClick={() => onPageChange(page - 1)}
+        disabled={page <= 1}
+        aria-label="前のページ"
+      >
+        ＜
+      </button>
+
+      {pages[0] > 1 && (
+        <>
+          <button className={styles.pageButton} onClick={() => onPageChange(1)}>1</button>
+          {pages[0] > 2 && <span className={styles.pageInfo}>…</span>}
+        </>
+      )}
+
+      {pages.map((p) => (
+        <button
+          key={p}
+          className={`${styles.pageButton} ${p === page ? styles.pageButtonActive : ""}`}
+          onClick={() => onPageChange(p)}
+          aria-current={p === page ? "page" : undefined}
+        >
+          {p}
+        </button>
+      ))}
+
+      {pages[pages.length - 1] < totalPages && (
+        <>
+          {pages[pages.length - 1] < totalPages - 1 && <span className={styles.pageInfo}>…</span>}
+          <button className={styles.pageButton} onClick={() => onPageChange(totalPages)}>{totalPages}</button>
+        </>
+      )}
+
+      <button
+        className={styles.pageButton}
+        onClick={() => onPageChange(page + 1)}
+        disabled={page >= totalPages}
+        aria-label="次のページ"
+      >
+        ＞
+      </button>
+    </nav>
+  )
+}
+
+// ──────────────────────────────────────────────
+// メインコンポーネント: SearchResultList
+// ──────────────────────────────────────────────
+
+export default function SearchResultList({
+  articles,
+  loading,
+  error,
+  page,
+  totalPages,
+  onPageChange,
+}: Props) {
+  if (loading) {
+    return <p className={styles.loadingText}>検索中...</p>
+  }
+
+  if (error) {
+    return <p className={styles.errorText}>{error}</p>
+  }
+
+  if (articles.length === 0) {
+    return <p className={styles.emptyText}>検索結果がありません。キーワードを変えてお試しください。</p>
+  }
+
+  return (
+    <>
+      <div className={styles.resultList}>
+        {articles.map((article) => (
+          <ResultCard key={article.id} article={article} />
+        ))}
+      </div>
+      <Pagination page={page} totalPages={totalPages} onPageChange={onPageChange} />
+    </>
+  )
+}"},{"fileName":"app/components/SearchResultView.tsx","patch":"@@ -0,0 +1,296 @@
+"use client"
+
+import React, { useCallback, useEffect, useState } from "react"
+import { useRouter, useSearchParams } from "next/navigation"
+import Sidebar from "./Sidebar"
+import SearchResultList, { Article } from "./SearchResultList"
+import SearchSidebar, { Tag } from "./SearchSidebar"
+import fetcher from "../lib/fetcher"
+import dashStyles from "../styles/dashboard.module.css"
+import styles from "../styles/search_list.module.css"
+
+// ──────────────────────────────────────────────
+// 型定義
+// ──────────────────────────────────────────────
+
+type KnowledgeApiResponse = {
+  content?: Article[]
+  data?: Article[]
+  items?: Article[]
+  totalElements?: number
+  totalPages?: number
+  total?: number
+  totalCount?: number
+} | Article[]
+
+type TagApiResponse = {
+  content?: Tag[]
+  data?: Tag[]
+} | Tag[]
+
+const PAGE_SIZE = 20
+
+function parsePositiveInt(value: string | null): number | null {
+  if (!value) return null
+  const parsed = Number.parseInt(value, 10)
+  if (Number.isNaN(parsed) || parsed < 1) return null
+  return parsed
+}
+
+function normalizeType(value: string | null): "new" | "recommended" | null {
+  if (value === "new" || value === "recommended") return value
+  return null
+}
+
+// ──────────────────────────────────────────────
+// メインコンポーネント: SearchResultView
+// ──────────────────────────────────────────────
+
+export default function SearchResultView() {
+  const searchParams = useSearchParams()
+  const router = useRouter()
+
+  // クエリパラメータ
+  const [query, setQuery] = useState(searchParams.get("q") ?? "")
+  const [inputValue, setInputValue] = useState(searchParams.get("q") ?? "")
+  const [selectedTags, setSelectedTags] = useState<string[]>(() => {
+    const t = searchParams.get("tags")
+    return t ? t.split(",").filter(Boolean) : []
+  })
+  const [type, setType] = useState<"new" | "recommended" | null>(
+    normalizeType(searchParams.get("type")),
+  )
+  const [limit, setLimit] = useState<number | null>(
+    parsePositiveInt(searchParams.get("limit")),
+  )
+  const [page, setPage] = useState<number>(() => {
+    const p = parseInt(searchParams.get("page") ?? "1", 10)
+    return isNaN(p) || p < 1 ? 1 : p
+  })
+
+  // 検索結果
+  const [articles, setArticles] = useState<Article[]>([])
+  const [totalPages, setTotalPages] = useState(1)
+  const [totalCount, setTotalCount] = useState<number | null>(null)
+  const [articlesLoading, setArticlesLoading] = useState(false)
+  const [articlesError, setArticlesError] = useState<string | null>(null)
+
+  // タグ一覧
+  const [tags, setTags] = useState<Tag[]>([])
+  const [tagsLoading, setTagsLoading] = useState(true)
+
+  // URL クエリ更新時（戻る/進む等）にローカル状態へ同期する
+  useEffect(() => {
+    setQuery(searchParams.get("q") ?? "")
+    setInputValue(searchParams.get("q") ?? "")
+    const t = searchParams.get("tags")
+    setSelectedTags(t ? t.split(",").filter(Boolean) : [])
+    setType(normalizeType(searchParams.get("type")))
+    setLimit(parsePositiveInt(searchParams.get("limit")))
+    const p = parseInt(searchParams.get("page") ?? "1", 10)
+    setPage(isNaN(p) || p < 1 ? 1 : p)
+  }, [searchParams])
+
+  // ── URL を更新してクエリパラメータを反映する ──
+  const pushUrl = useCallback(
+    (newQuery: string, newTags: string[], newPage: number) => {
+      const params = new URLSearchParams()
+      if (newQuery.trim()) params.set("q", newQuery.trim())
+      if (newTags.length > 0) params.set("tags", newTags.join(","))
+      if (newPage > 1) params.set("page", String(newPage))
+      const qs = params.toString()
+      router.push(`/search_list${qs ? `?${qs}` : ""}`)
+    },
+    [router],
+  )
+
+  // ── 検索 API 呼び出し ──
+  useEffect(() => {
+    let cancelled = false
+    async function loadArticles() {
+      setArticlesLoading(true)
+      setArticlesError(null)
+      try {
+        const params = new URLSearchParams()
+        if (query.trim()) params.set("q", query.trim())
+        if (selectedTags.length > 0) params.set("tags", selectedTags.join(","))
+        if (type === "new") params.set("filter", "latest")
+        if (type === "recommended") params.set("filter", "recommended")
+
+        const pageSize = limit ?? PAGE_SIZE
+        params.set("page", String(page - 1)) // API は 0-indexed ページネーションを想定
+        params.set("size", String(pageSize))
+
+        const res = await fetcher<KnowledgeApiResponse>(
+          `/api/v1/knowledge?${params.toString()}`
+        )
+
+        if (cancelled) return
+
+        if (Array.isArray(res)) {
+          setArticles(res)
+          setTotalCount(res.length)
+          setTotalPages(1)
+        } else {
+          const items =
+            (res as { content?: Article[]; data?: Article[] }).content ??
+            (res as { content?: Article[]; data?: Article[] }).data ??
+            (res as { items?: Article[] }).items ??
+            []
+          setArticles(items)
+
+          const total =
+            (res as { totalElements?: number }).totalElements ??
+            (res as { total?: number }).total ??
+            (res as { totalCount?: number }).totalCount ??
+            items.length
+          setTotalCount(total)
+          setTotalPages(
+            (res as { totalPages?: number }).totalPages ??
+            (Math.ceil(total / pageSize) || 1)
+          )
+        }
+      } catch (err: unknown) {
+        if (!cancelled) {
+          setArticlesError("検索結果の取得に失敗しました。しばらく後で再試行してください。")
+        }
+      } finally {
