+          <button
+            onClick={handleLogout}
+            className={styles.logoutButton}
+          >
+            ログアウト
+          </button>
+        </>
+      )}
+    </nav>
+  )
+}"},{"fileName":"app/dashboard/page.tsx","patch":"@@ -0,0 +1,17 @@
