export type Article = {
  id: number | string
  title: string
  excerpt?: string
  author?: string
  publishedAt?: string
  tags?: string[]
}

export type Tag = {
  id?: number | string
  name: string
  count?: number
}

export type ListApiResponse<T> = {
  content?: T[]
  data?: T[]
  items?: T[]
} | T[]

export function normalizeListResponse<T>(res: ListApiResponse<T>): T[] {
  if (Array.isArray(res)) return res
  return res.content ?? res.data ?? res.items ?? []
}

"use client"

import React, { useEffect, useRef, useState } from "react"
import { useRouter } from "next/navigation"
import fetcher from "../lib/fetcher"
import { type Article, type ListApiResponse, normalizeListResponse } from "../lib/types"
import quickSearchStyles from "./QuickSearch.module.css"

/** GET /api/v1/knowledge のレスポンス型（配列要素） */
type KnowledgeItem = Article

type ApiResponse = ListApiResponse<KnowledgeItem>

/** サジェスト付きクイック検索コンポーネント */
export default function QuickSearch() {
  const [query, setQuery] = useState("")
  const [suggestions, setSuggestions] = useState<KnowledgeItem[]>([])
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const wrapRef = useRef<HTMLDivElement>(null)
  const router = useRouter()

  // クリックアウトサイドでサジェストを閉じる
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [])

  // デバウンスでサジェスト取得
  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current)
    if (!query.trim()) {
      setSuggestions([])
      setOpen(false)
      return
    }

    debounceRef.current = setTimeout(async () => {
      setLoading(true)
      setError(null)
      try {
        const res = await fetcher<ApiResponse>(
          `/api/v1/knowledge?q=${encodeURIComponent(query.trim())}&size=5`
        )
        const items = normalizeListResponse(res)
        setSuggestions(items)
        setOpen(items.length > 0)
      } catch (err: unknown) {
        setError("検索に失敗しました。")
      } finally {
        setLoading(false)
      }
    }, 300)

    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [query])

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!query.trim()) return
    router.push(`/search_list?q=${encodeURIComponent(query.trim())}`)
    setOpen(false)
  }

  function handleSelect(item: KnowledgeItem) {
    router.push(`/knowledge/${item.id}`)
    setOpen(false)
    setQuery("")
  }

  return (
    <div ref={wrapRef} className={quickSearchStyles.wrap}>
      <form onSubmit={handleSubmit} role="search" aria-label="ナレッジ検索" className={quickSearchStyles.form}>
        <span className={quickSearchStyles.icon} aria-hidden="true">🔍</span>
        <input
          className={quickSearchStyles.input}
          type="search"
          placeholder="ナレッジを検索…"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => suggestions.length > 0 && setOpen(true)}
          aria-label="ナレッジ検索"
          aria-expanded={open}
          aria-autocomplete="list"
          aria-controls="qs-suggestions"
          autoComplete="off"
        />
        {loading && <span className={quickSearchStyles.spinner} aria-label="検索中" />}
        {query && (
          <button
            type="button"
            className={quickSearchStyles.clearBtn}
            onClick={() => { setQuery(""); setSuggestions([]); setOpen(false) }}
            aria-label="クリア"
          >✕</button>
        )}
        <button type="submit" className={quickSearchStyles.searchBtn}>検索</button>
      </form>

      {error && <p className={quickSearchStyles.error}>{error}</p>}

      {open && (
        <ul
          id="qs-suggestions"
          role="listbox"
          className={quickSearchStyles.dropdown}
          aria-label="サジェスト一覧"
        >
          {suggestions.map((item) => (
            <li
              key={item.id}
              role="option"
              aria-selected={false}
              className={quickSearchStyles.dropdownItem}
              onMouseDown={() => handleSelect(item)}
            >
              <span className={quickSearchStyles.dropdownIcon} aria-hidden="true">📄</span>
              <span className={quickSearchStyles.dropdownTitle}>{item.title}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

"use client"

import React, { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import fetcher from "../lib/fetcher"
import { type ListApiResponse, type Tag, normalizeListResponse } from "../lib/types"
import quickTagsStyles from "./QuickTags.module.css"

/** GET /api/v1/tags のレスポンス型（配列要素） */
type ApiResponse = ListApiResponse<Tag>

/** クイック操作（タグ一覧）コンポーネント */
export default function QuickTags() {
  const [tags, setTags] = useState<Tag[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const router = useRouter()

  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        const res = await fetcher<ApiResponse>("/api/v1/tags")
        if (cancelled) return
        const items = normalizeListResponse(res)
        setTags(items)
      } catch (err: unknown) {
        if (!cancelled) setError("タグの取得に失敗しました。")
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    load()
    return () => { cancelled = true }
  }, [])

  function handleTagClick(tag: Tag) {
    router.push(`/search_list?tags=${encodeURIComponent(tag.name)}`)
  }

  return (
    <div className={quickTagsStyles.wrap}>
      {loading && <p className={quickTagsStyles.loading}>タグを読み込み中...</p>}
      {error && <p className={quickTagsStyles.error}>{error}</p>}
      {!loading && !error && tags.length === 0 && (
        <p className={quickTagsStyles.empty}>タグがありません。</p>
      )}
      {!loading && tags.length > 0 && (
        <ul className={quickTagsStyles.tagList} aria-label="タグ一覧">
          {tags.map((tag) => (
            <li key={tag.id}>
              <button
                type="button"
                className={quickTagsStyles.tagChip}
                onClick={() => handleTagClick(tag)}
                aria-label={`タグ: ${tag.name}`}
              >
                <span className={quickTagsStyles.tagHash}>#</span>
                {tag.name}
                {tag.count != null && (
                  <span className={quickTagsStyles.tagCount}>{tag.count}</span>
                )}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

"use client"

import React from "react"
import Link from "next/link"
import { type Article } from "../lib/types"
import styles from "../styles/search_list.module.css"

// ──────────────────────────────────────────────
// 型定義
// ──────────────────────────────────────────────

type Props = {
  articles: Article[]
  loading: boolean
  error: string | null
  /** 現在のページ番号（1始まり） */
  page: number
  /** 総ページ数 */
  totalPages: number
  onPageChange: (page: number) => void
}

// ──────────────────────────────────────────────
// サブコンポーネント: 検索結果カード
// ──────────────────────────────────────────────

function ResultCard({ article }: { article: Article }) {
  return (
    <article className={styles.resultCard}>
      <Link href={`/knowledge/${article.id}`} className={styles.resultCardLink}>
        {article.title}
      </Link>

      {article.excerpt && (
        <p className={styles.resultCardExcerpt}>{article.excerpt}</p>
      )}

      {article.tags && article.tags.length > 0 && (
        <div className={styles.tagChipList}>
          {article.tags.map((tag) => (
            <span key={tag} className={styles.tagChip}>{tag}</span>
          ))}
        </div>
      )}

      <div className={styles.resultCardMeta}>
        {article.author && <span>投稿者: {article.author}</span>}
        {article.publishedAt && (
          <span>
            {new Date(article.publishedAt).toLocaleDateString("ja-JP")}
          </span>
        )}
      </div>
    </article>
  )
}

// ──────────────────────────────────────────────
// サブコンポーネント: ページネーション
// ──────────────────────────────────────────────

function Pagination({
  page,
  totalPages,
  onPageChange,
}: {
  page: number
  totalPages: number
  onPageChange: (p: number) => void
}) {
  if (totalPages <= 1) return null

  const pages: number[] = []
  const delta = 2
  for (let i = Math.max(1, page - delta); i <= Math.min(totalPages, page + delta); i++) {
    pages.push(i)
  }

  return (
    <nav className={styles.pagination} aria-label="ページネーション">
      <button
        className={styles.pageButton}
        onClick={() => onPageChange(page - 1)}
        disabled={page <= 1}
        aria-label="前のページ"
      >
        ＜
      </button>

      {pages[0] > 1 && (
        <>
          <button className={styles.pageButton} onClick={() => onPageChange(1)}>1</button>
          {pages[0] > 2 && <span className={styles.pageInfo}>…</span>}
        </>
      )}

      {pages.map((p) => (
        <button
          key={p}
          className={`${styles.pageButton} ${p === page ? styles.pageButtonActive : ""}`}
          onClick={() => onPageChange(p)}
          aria-current={p === page ? "page" : undefined}
        >
          {p}
        </button>
      ))}

      {pages[pages.length - 1] < totalPages && (
        <>
          {pages[pages.length - 1] < totalPages - 1 && <span className={styles.pageInfo}>…</span>}
          <button className={styles.pageButton} onClick={() => onPageChange(totalPages)}>{totalPages}</button>
        </>
      )}

      <button
        className={styles.pageButton}
        onClick={() => onPageChange(page + 1)}
        disabled={page >= totalPages}
        aria-label="次のページ"
      >
        ＞
      </button>
    </nav>
  )
}

// ──────────────────────────────────────────────
// メインコンポーネント: SearchResultList
// ──────────────────────────────────────────────

export default function SearchResultList({
  articles,
  loading,
  error,
  page,
  totalPages,
  onPageChange,
}: Props) {
  if (loading) {
    return <p className={styles.loadingText}>検索中...</p>
  }

  if (error) {
    return <p className={styles.errorText}>{error}</p>
  }

  if (articles.length === 0) {
    return <p className={styles.emptyText}>検索結果がありません。キーワードを変えてお試しください。</p>
  }

  return (
    <>
      <div className={styles.resultList}>
        {articles.map((article) => (
          <ResultCard key={article.id} article={article} />
        ))}
      </div>
      <Pagination page={page} totalPages={totalPages} onPageChange={onPageChange} />
    </>
  )
}

"use client"

