  totalCount?: number
} | Article[]

type TagApiResponse = ListApiResponse<Tag>

const PAGE_SIZE = 20

function parsePositiveInt(value: string | null): number | null {
  if (!value) return null
  const parsed = Number.parseInt(value, 10)
  if (Number.isNaN(parsed) || parsed < 1) return null
  return parsed
}

function normalizeType(value: string | null): "new" | "recommended" | null {
  if (value === "new" || value === "recommended") return value
  return null
}

// ──────────────────────────────────────────────
// メインコンポーネント: SearchResultView
// ──────────────────────────────────────────────

export default function SearchResultView() {
  const searchParams = useSearchParams()
  const router = useRouter()

  // クエリパラメータ
  const [query, setQuery] = useState(searchParams.get("q") ?? "")
  const [inputValue, setInputValue] = useState(searchParams.get("q") ?? "")
  const [selectedTags, setSelectedTags] = useState<string[]>(() => {
    const t = searchParams.get("tags")
    return t ? t.split(",").filter(Boolean) : []
  })
  const [type, setType] = useState<"new" | "recommended" | null>(
    normalizeType(searchParams.get("type")),
  )
  const [limit, setLimit] = useState<number | null>(
    parsePositiveInt(searchParams.get("limit")),
  )
  const [page, setPage] = useState<number>(() => {
    const p = parseInt(searchParams.get("page") ?? "1", 10)
    return isNaN(p) || p < 1 ? 1 : p
  })

  // 検索結果
  const [articles, setArticles] = useState<Article[]>([])
  const [totalPages, setTotalPages] = useState(1)
  const [totalCount, setTotalCount] = useState<number | null>(null)
  const [articlesLoading, setArticlesLoading] = useState(false)
  const [articlesError, setArticlesError] = useState<string | null>(null)

  // タグ一覧
  const [tags, setTags] = useState<Tag[]>([])
  const [tagsLoading, setTagsLoading] = useState(true)

  // URL クエリ更新時（戻る/進む等）にローカル状態へ同期する
  useEffect(() => {
    setQuery(searchParams.get("q") ?? "")
    setInputValue(searchParams.get("q") ?? "")
    const t = searchParams.get("tags")
    setSelectedTags(t ? t.split(",").filter(Boolean) : [])
    setType(normalizeType(searchParams.get("type")))
    setLimit(parsePositiveInt(searchParams.get("limit")))
    const p = parseInt(searchParams.get("page") ?? "1", 10)
    setPage(isNaN(p) || p < 1 ? 1 : p)
  }, [searchParams])

  // ── URL を更新してクエリパラメータを反映する ──
  const pushUrl = useCallback(
    (
      newQuery: string,
      newTags: string[],
      newPage: number,
      curType: "new" | "recommended" | null = type,
      curLimit: number | null = limit,
    ) => {
      const params = new URLSearchParams()
      if (newQuery.trim()) params.set("q", newQuery.trim())
      if (newTags.length > 0) params.set("tags", newTags.join(","))
      if (curType) params.set("type", curType)
      if (curLimit) params.set("limit", String(curLimit))
      if (newPage > 1) params.set("page", String(newPage))
      const qs = params.toString()
      router.push(`/search_list${qs ? `?${qs}` : ""}`)
    },
    [router, type, limit],
  )

  // ── 検索 API 呼び出し ──
  useEffect(() => {
    let cancelled = false
    async function loadArticles() {
      setArticlesLoading(true)
      setArticlesError(null)
      try {
        const params = new URLSearchParams()
        if (query.trim()) params.set("q", query.trim())
        if (selectedTags.length > 0) params.set("tags", selectedTags.join(","))
        if (type === "new") params.set("filter", "latest")
        if (type === "recommended") params.set("filter", "recommended")

        const pageSize = limit ?? PAGE_SIZE
        params.set("page", String(page - 1)) // API は 0-indexed ページネーションを想定
        params.set("size", String(pageSize))

        const res = await fetcher<KnowledgeApiResponse>(
          `/api/v1/knowledge?${params.toString()}`
        )

        if (cancelled) return

        if (Array.isArray(res)) {
          setArticles(res)
          setTotalCount(res.length)
          setTotalPages(1)
        } else {
          const items = normalizeListResponse(res)
          setArticles(items)

          const total =
            (res as { totalElements?: number }).totalElements ??
            (res as { total?: number }).total ??
            (res as { totalCount?: number }).totalCount ??
            items.length
          setTotalCount(total)
          setTotalPages(
            (res as { totalPages?: number }).totalPages ??
            (Math.ceil(total / pageSize) || 1)
          )
        }
      } catch (err: unknown) {
        if (!cancelled) {
          setArticlesError("検索結果の取得に失敗しました。しばらく後で再試行してください。")
        }
      } finally {
        if (!cancelled) setArticlesLoading(false)
      }
    }
    loadArticles()
    return () => { cancelled = true }
  }, [query, selectedTags, page, type, limit])

  // ── タグ一覧 API 呼び出し ──
  useEffect(() => {
    let cancelled = false
    async function loadTags() {
      try {
        const res = await fetcher<TagApiResponse>("/api/v1/tags")
        if (cancelled) return
        const items = normalizeListResponse(res)
        setTags(items)
      } catch {
        // タグ取得失敗はサイレントに処理
      } finally {
        if (!cancelled) setTagsLoading(false)
      }
    }
    loadTags()
    return () => { cancelled = true }
  }, [])

  // ── イベントハンドラ ──

  function handleSearchSubmit(e: React.FormEvent) {
    e.preventDefault()
    const newQuery = inputValue.trim()
    setQuery(newQuery)
    setPage(1)
    pushUrl(newQuery, selectedTags, 1)
  }

  function handleTagClick(tagName: string) {
    const newTags = selectedTags.includes(tagName)
      ? selectedTags.filter((t) => t !== tagName)
      : [...selectedTags, tagName]
    setSelectedTags(newTags)
    setPage(1)
    pushUrl(query, newTags, 1)
  }

  function handlePageChange(newPage: number) {
    setPage(newPage)
    pushUrl(query, selectedTags, newPage)
    // ページ変更時にスクロール位置をトップへ戻す
    window.scrollTo({ top: 0, behavior: "smooth" })
  }

  // ── レンダリング ──

  return (
    <div className={dashStyles.container}>
      {/* ── 左ナビ（共通 Sidebar コンポーネント） ── */}
      <Sidebar activeItem="knowledge" />

      {/* ── コンテンツエリア（main + 右サイドバー） ── */}
      <div className={dashStyles.contentArea}>
        <main className={dashStyles.main} id="main-content">
          {/* ページヘッダー */}
          <div className={styles.pageHeader}>
            <h1 className={styles.pageTitle}>検索結果</h1>
            {query && (
              <p className={styles.queryLabel}>
                「<span className={styles.queryText}>{query}</span>」の検索結果
                {selectedTags.length > 0 && (
                  <> &nbsp;／&nbsp; タグ: {selectedTags.join(", ")}</>
                )}
              </p>
            )}
            {!query && type === "new" && (
              <p className={styles.queryLabel}>新着記事の一覧を表示しています。</p>
            )}
            {!query && type === "recommended" && (
              <p className={styles.queryLabel}>おすすめ記事の一覧を表示しています。</p>
            )}
          </div>

          {/* 検索バー */}
          <form
            className={styles.searchBarForm}
            onSubmit={handleSearchSubmit}
            role="search"
            aria-label="記事検索"
          >
            <input
              type="search"
              className={styles.searchInput}
              placeholder="キーワードを入力して検索…"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              aria-label="検索キーワード"
            />
            <button type="submit" className={styles.searchButton}>
              検索
            </button>
          </form>

          {/* 検索結果リスト */}
          <section aria-labelledby="section-results">
            <h2 className={dashStyles.sectionTitle} id="section-results">
              {articlesLoading
                ? "検索中..."
                : totalCount !== null
                ? `${totalCount.toLocaleString("ja-JP")} 件の結果`
                : "検索結果"}
            </h2>
            <SearchResultList
              articles={articles}
              loading={articlesLoading}
              error={articlesError}
              page={page}
              totalPages={totalPages}
              onPageChange={handlePageChange}
            />
          </section>
        </main>

        {/* ── 右サイドバー ── */}
        <aside className={dashStyles.right} aria-label="検索サイドバー">
          <SearchSidebar
            totalCount={articlesLoading ? null : totalCount}
            tags={tags}
            tagsLoading={tagsLoading}
            selectedTags={selectedTags}
            onTagClick={handleTagClick}
          />
        </aside>
      </div>
    </div>
  )
}

"use client"

import React, { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import Link from "next/link"
import Sidebar from "./Sidebar"
import fetcher from "../lib/fetcher"
import { type Article, type ListApiResponse, normalizeListResponse } from "../lib/types"
import styles from "../styles/dashboard.module.css"

// ──────────────────────────────────────────────
// 型定義
// ──────────────────────────────────────────────

type SummaryData = {
  totalPosts?: number
  weeklyPosts?: number
  pendingApprovals?: number
}

type ActivityDayItem = {
  date: string
  posts: number
  comments: number
  likes: number
}

type ActivityResponse = {
  range?: string
  from?: string
  to?: string
  items?: ActivityDayItem[]
}

type WeeklyActivityTotals = {
  posts: number
  comments: number
  likes: number
}

type ArticleApiResponse = ListApiResponse<Article>

// ──────────────────────────────────────────────
// サブコンポーネント: 記事カード
// ──────────────────────────────────────────────

function ArticleCard({ article }: { article: Article }) {
  return (
    <div className={styles.articleCard}>
      <Link href={`/knowledge/${article.id}`} className={styles.articleCardLink}>
        {article.title}
      </Link>
      {article.excerpt && (
        <p className={styles.articleCardExcerpt}>{article.excerpt}</p>
      )}
      <div className={styles.articleCardMeta}>
        {article.author && <span>作成者: {article.author}</span>}
        {article.publishedAt && (
          <span>{new Date(article.publishedAt).toLocaleDateString("ja-JP")}</span>
        )}
      </div>
    </div>
  )
}

// ──────────────────────────────────────────────
// メインコンポーネント: Dashboard
// ──────────────────────────────────────────────

export default function Dashboard() {
  const router = useRouter()
  const [authChecked, setAuthChecked] = useState(false)

  // 認証ガード: トークン未存在の場合は /login へリダイレクト
  useEffect(() => {
    const token = localStorage.getItem('token')
    if (!token) {
      router.replace('/login')
      return
    }
    setAuthChecked(true)
  }, [router])

  // 記事データ
  const [recommendedArticle, setRecommendedArticle] = useState<Article | null>(null)
  const [latestArticles, setLatestArticles] = useState<Article[]>([])
  const [articlesLoading, setArticlesLoading] = useState(true)
  const [articlesError, setArticlesError] = useState<string | null>(null)

  // サマリーデータ
  const [summary, setSummary] = useState<SummaryData | null>(null)
  const [weeklyActivity, setWeeklyActivity] = useState<WeeklyActivityTotals | null>(null)
  const [summaryLoading, setSummaryLoading] = useState(true)
  const [isAdmin, setIsAdmin] = useState(false)

  // 管理者判定（localStorage から currentUser を読み取り）
  useEffect(() => {
    try {
      const userJson = localStorage.getItem('currentUser')
      if (userJson) {
        const user = JSON.parse(userJson)
        setIsAdmin(
          !!(
            user?.isAdmin ||
            user?.admin ||
            user?.username === 'admin' ||
            user?.email === 'admin@naviai.com' ||
            (user?.roles ?? []).includes('ADMIN') ||
            (user?.roles ?? []).includes('ROLE_ADMIN')
          )
        )
      }
    } catch {}
  }, [])

  // 記事取得
  useEffect(() => {
    let cancelled = false
    async function loadArticles() {
      try {
        const [latestRes, recommendedRes] = await Promise.all([
          fetcher<ArticleApiResponse>("/api/v1/knowledge?filter=latest&size=3"),
          fetcher<ArticleApiResponse>("/api/v1/knowledge?filter=recommended&size=1"),
        ])
        if (cancelled) return
        const recommendedArr = normalizeListResponse(recommendedRes)
        setRecommendedArticle(recommendedArr[0] ?? null)
        setLatestArticles(normalizeListResponse(latestRes).slice(0, 3))
      } catch {
        if (!cancelled) setArticlesError("記事の取得に失敗しました。")
      } finally {
        if (!cancelled) setArticlesLoading(false)
      }
    }
    loadArticles()
    return () => { cancelled = true }
  }, [])

  // サマリー取得
  useEffect(() => {
    let cancelled = false
    async function loadSummary() {
      try {
        const toDate = new Date()
        const fromDate = new Date(toDate)
        fromDate.setDate(fromDate.getDate() - 6)
        const toStr = toDate.toISOString().slice(0, 10)
        const fromStr = fromDate.toISOString().slice(0, 10)

        const [summaryRes, activityRes] = await Promise.all([
          fetcher<SummaryData>("/api/v1/dashboard"),
          fetcher<ActivityResponse>(`/api/v1/dashboard/activity?from=${fromStr}&to=${toStr}`),
        ])

        if (cancelled) return

        setSummary(summaryRes)
        const totals = (activityRes.items ?? []).reduce(
          (acc, item) => {
            acc.posts += item.posts ?? 0
            acc.comments += item.comments ?? 0
            acc.likes += item.likes ?? 0
            return acc
          },
          { posts: 0, comments: 0, likes: 0 }
        )
        setWeeklyActivity(totals)
      } catch {
        // サマリー取得失敗はサイレント
      } finally {
        if (!cancelled) setSummaryLoading(false)
      }
    }
    loadSummary()
    return () => { cancelled = true }
  }, [])

  if (!authChecked) return null

  return (
    <div className={styles.container}>

      {/* ── 左ナビ（共通 Sidebar コンポーネント） ── */}
      <Sidebar activeItem="dashboard" />

      {/* ── コンテンツエリア（main + 右サイドバー） ── */}
      <div className={styles.contentArea}>
      <main className={styles.main} id="main-content">
        <div className={styles.pageHeader}>
          <h1 className={styles.pageTitle}>ダッシュボード</h1>
        </div>

        {/* クイック操作ボタン */}
        <div className={styles.quickActions}>
          <Link
            href="/search_list?type=new&limit=20"
            className={styles.quickActionBtn}
          >
            新着記事
          </Link>
          <Link
            href="/search_list?type=recommended&limit=10"
            className={styles.quickActionBtn}
          >
            おすすめ記事
          </Link>
        </div>

        {/* おすすめ記事（1件・上段固定） */}
        <section aria-labelledby="section-recommended">
          <h2 className={styles.sectionTitle} id="section-recommended">おすすめ記事</h2>
          {articlesLoading && <p className={styles.loadingText}>記事を読み込み中...</p>}
          {articlesError && <p className={styles.errorText}>{articlesError}</p>}
          {!articlesLoading && !articlesError && (
            recommendedArticle
              ? <ArticleCard article={recommendedArticle} />
              : <p className={styles.loadingText}>記事がありません。</p>
          )}
        </section>

        {/* 新着記事（最大3件・下段） */}
        <section aria-labelledby="section-latest">
          <h2 className={styles.sectionTitle} id="section-latest">新着記事</h2>
          {articlesLoading && <p className={styles.loadingText}>記事を読み込み中...</p>}
          {articlesError && <p className={styles.errorText}>{articlesError}</p>}
          {!articlesLoading && !articlesError && (
            latestArticles.length > 0
              ? latestArticles.map((a) => <ArticleCard key={a.id} article={a} />)
              : <p className={styles.loadingText}>記事がありません。</p>
          )}
        </section>
      </main>

      {/* ── 右サイドバー ── */}
      <aside className={styles.right} aria-label="サマリーウィジェット">

        {/* 承認待ち（管理者のみ） */}
        {isAdmin && (
          <div className={styles.sidebarCard}>
            <h2 className={styles.sidebarTitle}>承認待ち</h2>
            {summaryLoading
              ? <p className={styles.loadingText}>読み込み中...</p>
              : <Link href="/admin/pending" className={styles.pendingCount} style={{ textDecoration: "none" }}>
                  {summary?.pendingApprovals ?? "—"}
                  <span className={styles.pendingUnit}>　件</span>
                </Link>
            }
          </div>
        )}

        {/* 週次アクティビティ（管理者のみ） */}
        {isAdmin && (
          <div className={styles.sidebarCard}>
            <h2 className={styles.sidebarTitle}>週次アクティビティ</h2>
            {summaryLoading
              ? <p className={styles.loadingText}>読み込み中...</p>
              : (
                <ul className={styles.statList}>
                  <li className={styles.statItem}>
                    <span>新着</span>
                    <span className={styles.statValue}>{weeklyActivity?.posts ?? "—"}</span>
                  </li>
                  <li className={styles.statItem}>
                    <span>コメント</span>
                    <span className={styles.statValue}>{weeklyActivity?.comments ?? "—"}</span>
                  </li>
                  <li className={styles.statItem}>
                    <span>いいね</span>
                    <span className={styles.statValue}>{weeklyActivity?.likes ?? "—"}</span>
                  </li>
                </ul>
              )
            }
          </div>
        )}

      </aside>
      </div>
    </div>
  )
}

"use client"

import React, { useState } from "react"
import { useRouter } from "next/navigation"
import Link from "next/link"
import LoginForm from "../components/LoginForm"
import styles from "../pages/login/login.module.css"
import { login } from "../lib/auth"
import fetcher from "../lib/fetcher"

type FormData = {
  email: string
  password: string
}

export default function LoginPage() {
  const router = useRouter()
  const [loading, setLoading] = useState(false)

  async function handleSubmit(data: FormData) {
    setLoading(true)
    try {
      // 1. ログイン API 呼び出し
      const res = await login(data.email, data.password)

      // 2. トークンを保存
      localStorage.setItem("token", res.token)
      localStorage.setItem("refreshToken", res.refreshToken)

      // 3. ユーザー情報取得（管理者判定含む）
      const me = await fetcher<{ id: number; username: string; email: string; displayName: string; roles?: string[]; isAdmin?: boolean }>("/api/v1/users/me")

      // 4. ユーザー情報をストレージへ保存（管理者フラグ含む）
      localStorage.setItem("currentUser", JSON.stringify(me))

      router.push("/dashboard")
    } catch (err: any) {
      // LoginForm 内の serverError に伝播させる
      throw new Error(err?.message || "ネットワークエラーが発生しました。")
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className={styles.container}>
      <div className={styles.centerCard}>
        <div className={styles.cardTop}>
          <div className={styles.headerIllustration} aria-hidden="true" />
          <div className={styles.cardTitle}>team sharing</div>
        </div>

        <div className={styles.cardBody}>
          <div className={styles.formWrap}>
            <LoginForm onSubmit={handleSubmit} loading={loading} />
          </div>

          <div className={styles.helpBox}>
            <div>まだアカウントをお持ちでないですか？</div>
            <div className={styles.helpSub}>
              <Link href="/register" className={styles.helpLink}>
                アカウント登録はこちら
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import fetcher from '../lib/fetcher'
import styles from '../styles/dashboard.module.css'

export type SidebarActiveItem =
  | 'dashboard'
  | 'knowledge'
  | 'my_post_list'
  | 'review'
  | 'admin'

type Props = {
  activeItem?: SidebarActiveItem
}

export default function Sidebar({ activeItem = 'dashboard' }: Props) {
  const router = useRouter()
  const [open, setOpen] = useState(true)
  const [isAdmin, setIsAdmin] = useState(false)

  // localStorage は SSR では使えないため useEffect で初期化
  useEffect(() => {
    try {
      const v = localStorage.getItem('leftNavOpen')
      setOpen(v === null ? true : v === '1')
      const userJson = localStorage.getItem('currentUser')
      if (userJson) {
        const user = JSON.parse(userJson)
        setIsAdmin(
          !!(
            user?.isAdmin ||
            user?.admin ||
            user?.username === 'admin' ||
            user?.email === 'admin@naviai.com' ||
            (user?.roles ?? []).includes('ADMIN') ||
            (user?.roles ?? []).includes('ROLE_ADMIN')
          )
        )
      }
    } catch {
      // localStorage が使えない環境では開いた状態をデフォルトとする
    }
  }, [])

  const toggle = () => {
    setOpen(prev => {
      const next = !prev
      try { localStorage.setItem('leftNavOpen', next ? '1' : '0') } catch {}
      return next
    })
  }

  const handleLogout = async () => {
    try {
      const refreshToken = localStorage.getItem('refreshToken')
      if (refreshToken) {
        await fetcher('/api/v1/auth/logout', {
          method: 'POST',
          body: JSON.stringify({ refreshToken }),
        })
      }
    } catch {
      // ログアウト API 失敗時もクライアント側は必ずクリア
    } finally {
      localStorage.removeItem('token')
      localStorage.removeItem('refreshToken')
      localStorage.removeItem('currentUser')
      localStorage.removeItem('leftNavOpen')
      router.replace('/login')
    }
  }

  return (
    <nav
      className={open ? styles.leftNav : `${styles.leftNav} ${styles.leftNavCollapsed}`}
      aria-label="サイドナビゲーション"
    >
      {/* ブランド行：常に表示 */}
      <div className={styles.leftBrand}>
        {open && <span className={styles.brandText}>Ginga</span>}
        <button
          aria-expanded={open}
          aria-label={open ? 'サイドバーを閉じる' : 'サイドバーを開く'}
          className={styles.sidebarToggleButton}
          onClick={toggle}
        >
          ☰
        </button>
      </div>

      {/* ナビリンク：開いているときのみ表示 */}
      {open && (
        <>
          <Link
            href="/dashboard"
            className={`${styles.navItem} ${activeItem === 'dashboard' ? styles.navItemActive : ''}`}
          >
            ダッシュボード
          </Link>
          <Link
            href="/dashboard/knowledge"
            className={`${styles.navItem} ${activeItem === 'knowledge' ? styles.navItemActive : ''}`}
          >
            ナレッジ
          </Link>
          <Link
            href="/my_post_list"
            className={`${styles.navItem} ${activeItem === 'my_post_list' ? styles.navItemActive : ''}`}
          >
            投稿一覧
          </Link>
          {isAdmin && (
            <>
              <Link
                href="/dashboard/review"
                className={`${styles.navItem} ${activeItem === 'review' ? styles.navItemActive : ''}`}
              >
                承認
              </Link>
              <Link
                href="/admin"
                className={`${styles.navItem} ${activeItem === 'admin' ? styles.navItemActive : ''}`}
              >
                管理者パネル
              </Link>
            </>
          )}
          <Link href="/posts/new" className={styles.newPostButton}>
            ＋ 新規投稿
          </Link>
