+/* ──────────────────────────────────────────────
+   外側ラッパー：横並び flex（サイドバー + コンテンツエリア）
+   サイドバーは左端から画面下まで伸びる
+────────────────────────────────────────────── */
+.container {
+  display: flex;
+  align-items: stretch;
+  min-height: calc(100vh - var(--topbar-height, 64px)); /* topbar 分を引いた全画面高 */
+}
+
+/* コンテンツエリア (main + right sidebar) */
+.contentArea {
+  flex: 1;
+  display: grid;
+  grid-template-columns: 1fr 320px;
+  gap: 24px;
+  align-items: start;
+  padding: 24px;
+  min-width: 0;
+}
+
+@media (max-width: 1024px) {
+  .contentArea {
+    grid-template-columns: 1fr;
+  }
+  .right {
+    display: none;
+  }
+}
+
+@media (max-width: 768px) {
+  .leftNav {
+    display: none;
+  }
+}
+
+/* ──────────────────────────────────────────────
+   Left nav：左端から画面下まで伸びる固定サイドバー
+────────────────────────────────────────────── */
+.leftNav {
+  flex-shrink: 0;
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+  background: var(--primary, #6fb1ff);
+  padding: 16px 8px;
+  width: 220px;
+  /* 左端から下端まで - border-radius なし */
+  border-radius: 0;
+  align-self: stretch;
+  transition: width 0.2s ease;
+}
+
+/* 閉じた状態：幅を最小化してリンクを非表示 */
+.leftNavCollapsed {
+  width: 56px;
+}
