+.leftBrand {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 8px 10px 16px;
+}
+
+.brandText {
+  font-weight: 800;
+  font-size: 16px;
+  color: #000; /* per spec: 黒い太字 */
+}
+
+.sidebarToggleButton {
+  background: transparent;
+  border: none;
