+.wrap {
+  position: relative;
+  width: 100%;
+  max-width: 640px;
+}
+
+.form {
+  display: flex;
+  align-items: center;
+  gap: var(--space-2);
+  background: var(--color-surface);
+  border: 1px solid var(--muted-ghost);
+  border-radius: var(--radius-md);
+  padding: 0 var(--space-3);
+  height: 48px;
+  box-shadow: var(--shadow-1);
+  transition: box-shadow 0.15s, border-color 0.15s;
+}
+
+.form:focus-within {
+  border-color: var(--color-primary);
+  box-shadow: 0 0 0 4px rgba(11, 61, 145, 0.08);
+}
+
+.icon {
+  font-size: 16px;
+  flex-shrink: 0;
+  color: var(--color-muted);
+}
+
+.input {
+  flex: 1;
+  border: 0;
+  background: transparent;
+  font-size: 15px;
+  color: #111827;
+  outline: none;
+  min-width: 0;
+}
+
+.input::placeholder {
+  color: var(--color-muted);
+}
+
+/* Remove browser-default search cancel button */
+.input::-webkit-search-cancel-button {
+  display: none;
+}
+
+.spinner {
+  display: inline-block;
+  width: 16px;
+  height: 16px;
+  border: 2px solid var(--muted-ghost);
+  border-top-color: var(--color-primary);
+  border-radius: 50%;
+  animation: spin 0.7s linear infinite;
+  flex-shrink: 0;
+}
+
+@keyframes spin {
+  to { transform: rotate(360deg) }
+}
+
+.clearBtn {
+  background: transparent;
+  border: 0;
+  color: var(--color-muted);
+  font-size: 14px;
+  cursor: pointer;
+  flex-shrink: 0;
+  padding: 0 4px;
+  line-height: 1;
+}
+
+.clearBtn:hover {
+  color: var(--color-danger);
+}
+
+.searchBtn {
+  background: var(--color-primary);
+  color: #fff;
+  border: 0;
+  border-radius: var(--radius-sm);
+  padding: 6px 14px;
+  font-size: 13px;
+  font-weight: 700;
+  cursor: pointer;
+  flex-shrink: 0;
+  transition: opacity 0.12s;
+}
+
+.searchBtn:hover {
+  opacity: 0.85;
+}
+
+/* Dropdown */
+.dropdown {
+  position: absolute;
+  top: calc(100% + 6px);
+  left: 0;
+  right: 0;
+  background: var(--color-surface);
+  border: 1px solid var(--muted-ghost);
+  border-radius: var(--radius-md);
+  box-shadow: var(--shadow-2);
+  list-style: none;
+  margin: 0;
+  padding: var(--space-1) 0;
+  z-index: 100;
+  overflow: hidden;
+}
+
+.dropdownItem {
+  display: flex;
+  align-items: center;
+  gap: var(--space-3);
+  padding: 10px var(--space-4);
+  cursor: pointer;
+  transition: background 0.1s;
+}
+
+.dropdownItem:hover {
+  background: #EFF3FA;
+}
+
+.dropdownIcon {
+  font-size: 15px;
+  flex-shrink: 0;
